\draw[thick,blue] (0,0) -- (1.8,1.6);
\node[rotate=90,font=\scriptsize] at (-0.5,1.1) {Attendance};
\node[font=\scriptsize] at (1.1,-0.5) {Weeks};
\node[font=\small] at (1.1,-1.1) {Graph P};
\end{scope}
\begin{scope}[xshift=3.0cm]
\draw[->] (0,0)--(0,2.2);
\draw[->] (0,0)--(2.4,0);
\draw[thick,blue,domain=0:1.8,smooth,variable=\x] plot ({\x},{0.494*\x*\x});
\node[rotate=90,font=\scriptsize] at (-0.5,1.1) {Attendance};
\node[font=\scriptsize] at (1.1,-0.5) {Weeks};
\node[font=\small] at (1.1,-1.1) {Graph Q};
\end{scope}
\begin{scope}[xshift=6.0cm]
\draw[->] (0,0)--(0,2.2);
\draw[->] (0,0)--(2.4,0);
\draw[thick,blue,domain=0:1.8,smooth,variable=\x] plot ({\x},{-0.494*(\x-1.8)*(\x-1.8)+1.6});
\node[rotate=90,font=\scriptsize] at (-0.5,1.1) {Attendance};
\node[font=\scriptsize] at (1.1,-0.5) {Weeks};
